import {safeFilename} from './pdf.js';

export async function preparePdfExport(blob,name){
  // Verify the generated bytes before handing them to a system file picker.
  if(new TextDecoder().decode(await blob.slice(0,5).arrayBuffer())!=='%PDF-')throw Error('The generated file is not a PDF. Please create it again.');
  const filename=`${safeFilename(name)}.pdf`;
  const file=new File([blob],filename,{type:'application/pdf'});
  // Safari may preview application/pdf download links instead of downloading.
  // Use a named binary attachment for download, while keeping PDF MIME for sharing/preview.
  const download=new File([blob],filename,{type:'application/octet-stream'});
  return {file,download};
}

export function pdfShareData(file){
  // File-only payload: some iOS share targets turn extra title/text into a text document.
  // The PDF already carries its filename, so no additional shared string is needed.
  return {files:[file]};
}
